<ContextEntityCard
entity={contextEntity}
onPreview={(entity) => showPreview(entity)}
onDeploy={(entity) => deployToProject(entity)}
onEdit={(entity) => openEditor(entity)}
onDelete={(entity) => confirmDelete(entity)}
