const { indexingMode, isLoading } = useIndexingMode();

// Only show toggle when mode is 'opt_in'
if (indexingMode === 'opt_in') {
return <IndexingToggle />;
}

// Automatic indexing when mode is 'on'
if (indexingMode === 'on') {
return <span>Indexing enabled globally</span>;
}
